int copy_creds(struct task_struct *p, unsigned long clone_flags) {
    struct cred *new;
    int ret;

    if ((clone_flags & (CLONE_NEWUSER | CLONE_THREAD | CLONE_SYSVSEM)))
        return 0;

    if (p->cred == NULL)
        return -EINVAL;

    if (clone_flags & CLONE_CREDENTIALS) {
        get_cred(p->cred);
        return 0;
    }

    new = prepare_creds();
    if (IS_ERR(new))
        return PTR_ERR(new);

    if (clone_flags & CLONE_NEWUSER) {
        ret = setup_new_userns(p, new);
        if (ret < 0) {
            abort_creds(new);
            return ret;
        }
    }

    if (clone_flags & CLONE_THREAD) {
        new->tkey = p->cred->tkey;
        if (new->tkey)
            key_get(new->tkey);
    }

    p->cred = new;
    return 0;
}

