#include <linux/slab.h>
#include <linux/cred.h>
#include <linux/key.h>
#include <linux/task.h>

int copy_credentials(struct task_struct *p, unsigned long clone_flags) {
    struct cred *new;
    int ret;

    new = prepare_creds();
    if (!new)
        return -ENOMEM;

    // Initialize the replacement session keyring to NULL
    new->session_keyring = NULL;

    // Check if the task should share credentials with its parent
    if (clone_flags & CLONE_NEWUSER) {
        // Handle user namespace creation
        ret = setup_new_userns(p, new);
        if (ret < 0)
            return ret;
    }

    if (clone_flags & CLONE_THREAD) {
        // Ensure process and session keyrings are shared appropriately among threads
        new->thread_keyring = p->cred->thread_keyring;
        get_keyring(new->thread_keyring);
        new->process_keyring = p->cred->process_keyring;
        get_keyring(new->process_keyring);
    }

    if (clone_flags & CLONE_CREDENTIALS) {
        // Prepare new credentials
        get_cred(new);
    } else {
        // Share credentials with the parent
        put_cred(new);
        new = get_cred(p->cred);
    }

    // Update the task's credentials
    set_cred(p, new);

    return 0;
}
